code='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r,c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r,c)])
            seen.add((r,c))
            pts = []
            while q:
                y,x = q.popleft(); pts.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            comps.append((min(y for y,x in pts), min(x for y,x in pts), color, pts))
    comps.sort(key=lambda z:(z[0],z[1]))
    out=[row[:] for row in grid]
    if len(comps) < 2:
        return out
    ry,rx,rc,ref=comps[0]
    ty,tx,tc,target=comps[1]
    ref_local={(y-ry,x-rx) for y,x in ref}
    target_local={(y-ty,x-tx) for y,x in target}
    for dy,dx in ref_local-target_local:
        y,x=ty+dy,tx+dx
        if 0 <= y < h and 0 <= x < w and out[y][x] == bg:
            out[y][x]=1
    return out
'''
